#!/bin/bash
set -e
echo "🚀 Area Spatial Scout: 最新プログラムの展開とCloud Run自動更新を開始します..."
mkdir -p ~/cloud_run_scout
cd ~/cloud_run_scout

python3 -c "
import base64, io, tarfile
b64 = ''
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(b64))) as t:
    t.extractall('.')
print('✅ 全プログラムの最新修正版（v2.2）を展開完了しました')
"

chmod +x deploy.sh
./deploy.sh
